SELECT id, customer_id, items, ship_to, attributes['device'] AS device, TRANSFORM(FILTER(items, i -> i.promo IS NOT NULL), i -> STRUCT(i.product_id AS pid, ROUND(i.price * 0.9, 2) AS discounted_price)) AS promo_lines, ARRAY_MAX(TRANSFORM(items, i -> i.price)) AS max_item_price, ARRAY_CONTAINS(MAP_KEYS(attributes), 'gift') AS has_gift, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code FROM carts WHERE customer_id IS NULL
